-- READ ONLY; bind @schema to reviewed target; do not assume table existence means Registry is enabled.
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema AND TABLE_NAME IN ('finance_invoice_request','finance_invoice','finance_receipt','finance_reconciliation','finance_contract_summary','finance_unclassified_income','finance_attachment') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,CONSTRAINT_NAME,CONSTRAINT_TYPE FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA=@schema AND TABLE_NAME IN ('finance_invoice_request','finance_invoice','finance_receipt','finance_reconciliation','finance_contract_summary','finance_unclassified_income','finance_attachment') ORDER BY TABLE_NAME,CONSTRAINT_NAME;
